// --- Helper: parse viewer count string like "4.1K viewers", "128K viewers", "1.2M viewers" ---
function parseViewers(text) {
  if (!text) return 0;
  const cleaned = text.replace(/[^0-9.KkMm]/g, '');
  const num = parseFloat(cleaned);
  if (isNaN(num)) return 0;
  if (/[Mm]/.test(cleaned)) return num * 1_000_000;
  if (/[Kk]/.test(cleaned)) return num * 1_000;
  return num;
}

// --- Gather all cards and their viewer counts ---
const allCards = Array.from(document.querySelectorAll('article.ghbJdj'));
if (allCards.length === 0) return;

const cardData = allCards.map(card => {
  const stat = card.querySelector('.tw-media-card-stat');
  const viewers = stat ? parseViewers(stat.textContent) : 0;
  return { card, viewers };
});

// --- Find top 3 threshold ---
const sorted = [...cardData].sort((a, b) => b.viewers - a.viewers);
const top3 = sorted.slice(0, 3).map(d => d.card);

const BADGE_ID = 'top-live-badge';

// --- For THIS element: add or remove badge ---
const myViewers = cardData.find(d => d.card === element)?.viewers ?? 0;
const isTop = top3.includes(element);

// Rank among top3
const rank = sorted.findIndex(d => d.card === element);

// Remove old badge first (idempotent: always reset)
const existing = element.querySelector('.' + BADGE_ID);
if (existing) existing.remove();

if (!isTop || myViewers === 0) return;

// --- Create badge ---
const badge = document.createElement('div');
badge.className = BADGE_ID;

const medals = ['🥇', '🥈', '🥉'];
const medal = medals[rank] || '🏆';

badge.textContent = medal + ' TOP LIVE';
badge.style.cssText = `
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 9999;
  background: linear-gradient(135deg, #ff0080, #ff6a00);
  color: #fff;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 20px;
  box-shadow: 0 2px 10px rgba(255,0,128,0.7), 0 0 0 2px rgba(255,255,255,0.3);
  pointer-events: none;
  white-space: nowrap;
  font-family: var(--font-display, sans-serif);
  animation: topLivePulse 1.6s ease-in-out infinite;
`;

// Inject pulse keyframe once
if (!document.getElementById('top-live-badge-style')) {
  const style = document.createElement('style');
  style.id = 'top-live-badge-style';
  style.textContent = `
    @keyframes topLivePulse {
      0%, 100% { box-shadow: 0 2px 10px rgba(255,0,128,0.7), 0 0 0 2px rgba(255,255,255,0.3); transform: scale(1); }
      50% { box-shadow: 0 4px 20px rgba(255,0,128,1), 0 0 0 3px rgba(255,255,255,0.5); transform: scale(1.05); }
    }
  `;
  document.head.appendChild(style);
}

// Attach to the thumbnail container so it overlays the preview image
const imageWrapper = element.querySelector('.ScWrapper-sc-1wvuch4-0');
if (imageWrapper) {
  imageWrapper.style.position = 'relative';
  imageWrapper.appendChild(badge);
}
